& =\frac{\pi}{6}
\end{aligned}
$$

Let $\sin ^{-1} \frac{3}{5}=x \Rightarrow \sin x=\frac{3}{5}$
Then,

$$
\cos x=\sqrt{1-\left(\frac{3}{5}\right)^{2}}=\frac{4}{5}
$$

Therefore,

$$
\begin{aligned}
\tan x & =\frac{3}{4} \\
x & =\tan ^{-1} \frac{3}{4} \\
\sin ^{-1} \frac{3}{5} & =\tan ^{-1} \frac{3}{4}
\end{aligned}
$$

Thus,

$$
\begin{aligned}
\text { LHS } & =2 \sin ^{-1} \frac{3}{5} \\
